func (this *Woo) HandleTickers(client any, message map[string]any) {
	//
	//     {
	//         "topic":"tickers",
	//         "ts":1618820615000,
	//         "data":[
	//             {
	//                 "symbol":"SPOT_OKB_USDT",
	//                 "open":16.297,
	//                 "close":17.183,
	//                 "high":24.707,
	//                 "low":11.997,
	//                 "volume":0,
	//                 "amount":0,
	//                 "count":0
	//             },
	//             {
	//                 "symbol":"SPOT_XRP_USDT",
	//                 "open":1.3515,
	//                 "close":1.43794,
	//                 "high":1.96674,
	//                 "low":0.39264,
	//                 "volume":750127.1,
	//                 "amount":985440.5122,
	//                 "count":396
	//             },
	//         ...
	//         ]
	//     }
	//
	var topic *string = this.SafeString(message, "topic")
	var data any = this.SafeValue(message, "data")
	var timestamp *int64 = this.SafeInteger(message, "ts")
	var result []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(data); i++ {
		var marketId *string = this.SafeString(ccxt.GetValue(data, i), "symbol")
		var market map[string]any = this.SafeMarket(marketId)
		var ticker map[string]any = ccxt.MapTyped(this.ParseWsTicker(this.Extend(ccxt.GetValue(data, i), map[string]any{
			"date": timestamp,
		}), market))
		ccxt.AddElementToObject(this.Tickers, market["symbol"], ticker)
		result = append(result, ticker)
	}
	client.(ccxt.ClientInterface).Resolve(result, topic)
}

/**
 * @method
 * @name woo#watchBidsAsks
 * @see https://docs.woox.io/#bbos
 * @description watches best bid & ask for symbols
 * @param {string[]} [symbols] unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Woo) WatchBidsAsksAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchBidsAsksBody(ch, optionalArgs...)
	return ch
}
func (this *Woo) watchBidsAsksBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var name string = "bbos"
	var topic string = name
	var request map[string]any = map[string]any{
		"event": "subscribe",
		"topic": topic,
	}
	var message map[string]any = this.Extend(request, params)

	bidsasks := (<-this.WatchPublicAsync(topic, message))
	ccxt.PanicOnError(bidsasks)
	if this.NewUpdates {

		ch <- bidsasks
		return nil
	}

	ch <- this.FilterByArray(this.Bidsasks, "symbol", symbolsNormalized)
	return nil
}

