func (this *Woo) unWatchOHLCVBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var timeframe string = ccxt.GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var market map[string]any = this.Market(symbol)
	var interval *string = this.SafeString(this.Timeframes, timeframe, timeframe)
	var topic string = "ohlcv"
	var name string = "kline"
	var subHash any = ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(market["id"], "@"), name), "_"), interval)
	params["symbolsAndTimeframes"] = []any{[]any{market["symbol"], timeframe}}

	ch <- ccxt.PanicOnError((<-this.UnwatchPublicAsync(subHash, market["symbol"], topic, params)))
	return nil
}
func (this *Woo) HandleOHLCV(client any, message map[string]any) {
	//
	//     {
	//         "topic":"SPOT_BTC_USDT@kline_1m",
	//         "ts":1618822432146,
	//         "data":{
	//             "symbol":"SPOT_BTC_USDT",
	//             "type":"1m",
	//             "open":56948.97,
	//             "close":56891.76,
	//             "high":56948.97,
	//             "low":56889.06,
	//             "volume":44.00947568,
	//             "amount":2504584.9,
	//             "startTime":1618822380000,
	//             "endTime":1618822440000
	//         }
	//     }
	//
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var topic *string = this.SafeString(message, "topic")
	var marketId *string = this.SafeString(data, "symbol")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var interval *string = this.SafeString(data, "type")
	var timeframe *string = this.FindTimeframe(interval)
	var parsed []any = []any{this.SafeInteger(data, "startTime"), this.SafeFloat(data, "open"), this.SafeFloat(data, "high"), this.SafeFloat(data, "low"), this.SafeFloat(data, "close"), this.SafeFloat(data, "volume")}
	ccxt.AddElementToObject(this.Ohlcvs, symbol, this.SafeDict(this.Ohlcvs, symbol, map[string]any{}))
	var stored any = this.SafeValue(this.SafeDict(this.Ohlcvs, symbol), timeframe)
	if ccxt.IsEqual(stored, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored = ccxt.NewArrayCacheByTimestamp(limit)
		if (symbol != nil) && (timeframe != nil) {
			ccxt.AddElementToObject(ccxt.GetValue(this.Ohlcvs, symbol), timeframe, stored)
		}
	}
	stored.(ccxt.Appender).Append(parsed)
	client.(ccxt.ClientInterface).Resolve(stored, topic)
}

