/**
 * @method
 * @name woo#watchOrders
 * @see https://docs.woox.io/#executionreport
 * @see https://docs.woox.io/#algoexecutionreportv2
 * @description watches information on multiple orders made by the user
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {bool} [params.trigger] true if trigger order
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Woo) WatchOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Woo) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var trigger *bool = this.SafeBool2(params, "stop", "trigger", false)
	var topic string = "executionreport"
	if trigger != nil && *trigger == true {
		topic = "algoexecutionreportv2"
	}
	var paramsOmitted map[string]any = ccxt.MapTyped(this.Omit(params, []any{"stop", "trigger"}))
	var messageHash any = topic
	var symbolResolved any = func() any {
		if symbol != nil {
			return this.Symbol(symbol)
		}
		return symbol
	}()
	if !ccxt.IsEqual(symbolResolved, nil) {
		messageHash = ccxt.Add(messageHash, ccxt.Add(":", symbolResolved))
	}
	var request map[string]any = map[string]any{
		"event": "subscribe",
		"topic": topic,
	}
	var message map[string]any = this.Extend(request, paramsOmitted)

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.WatchPrivateAsync(messageHash, message))))
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(symbolResolved, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbolResolved, since, limitResolved, true)
	return nil
}

