func (this *Woo) HandleErrorMessage(client any, message any) any {
	//
	// {"id":"1","event":"subscribe","success":false,"ts":1710780997216,"errorMsg":"Auth is needed."}
	//
	if !(ccxt.InOp(message, "success")) {
		return false
	}
	var success *bool = this.SafeBool(message, "success")
	if success != nil && *success == true {
		return false
	}
	var errorMessage *string = this.SafeString(message, "errorMsg")

	{
		ret__ := func(this *Woo) (ret_ any) {
			defer func() {
				if error := recover(); error != nil {
					if error == "break" {
						return
					}
					ret_ = func(this *Woo) any {
						// catch block:
						if ccxt.IsInstance(error, ccxt.AuthenticationError) {
							var messageHash string = "authenticated"
							client.(ccxt.ClientInterface).Reject(error, messageHash)
							if ccxt.InOp(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash) {
								ccxt.Remove(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
							}
						} else {
							client.(ccxt.ClientInterface).Reject(error)
						}
						return true

					}(this)
				}
			}()
			// try block:
			if errorMessage != nil {
				var feedback string = this.Id + " " + this.Json(message)
				this.ThrowExactlyMatchedException(this.Exceptions["exact"], errorMessage, feedback)
			}
			return false

		}(this)
		if ret__ != nil {
			return ret__
		}
		return nil
	}
}
func (this *Woo) HandleUnSubscription(client any, message map[string]any) {
	//
	//     {
	//         "id": "2",
	//         "event": "unsubscribe",
	//         "success": true,
	//         "ts": 1759568478343,
	//         "data": "SPOT_BTC_USDT@orderbook"
	//     }
	//
	var subscribeHash *string = this.SafeString(message, "data")
	var unsubscribeHash *string = ccxt.SafeStringPtr(ccxt.Add("unsubscribe::", subscribeHash))
	var subscription any = this.SafeDict(client.(ccxt.ClientInterface).GetSubscriptions(), unsubscribeHash, map[string]any{})
	var subMessageHashes []any = ccxt.SafeListTyped(subscription, "subMessageHashes")
	var unsubMessageHashes []any = ccxt.SafeListTyped(subscription, "unsubMessageHashes")
	for i := 0; i < len(subMessageHashes); i++ {
		var subHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(subMessageHashes) {
				return ccxt.DerefScalar(subMessageHashes[i])
			}
			return nil
		}())
		var unsubHash *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(unsubMessageHashes) {
				return ccxt.DerefScalar(unsubMessageHashes[i])
			}
			return nil
		}())
		this.CleanUnsubscription(ccxt.AsClient(client), subHash, unsubHash)
	}
	this.CleanCache(subscription)
}
func (this *Woo) HandleMessage(client any, message any) {
	if ccxt.IsEqual(this.HandleErrorMessage(client, message), true) {
		return
	}
	var methods map[string]any = map[string]any{
		"ping":                  this.HandlePing,
		"pong":                  this.HandlePong,
		"subscribe":             this.HandleSubscribe,
		"unsubscribe":           this.HandleUnSubscription,
		"orderbook":             this.HandleOrderBook,
		"orderbookupdate":       this.HandleOrderBook,
		"ticker":                this.HandleTicker,
		"tickers":               this.HandleTickers,
		"kline":                 this.HandleOHLCV,
		"auth":                  this.HandleAuth,
		"executionreport":       this.HandleOrderUpdate,
		"algoexecutionreportv2": this.HandleOrderUpdate,
		"trade":                 this.HandleTrade,
		"balance":               this.HandleBalance,
		"position":              this.HandlePositions,
		"bbos":                  this.HandleBidAsk,
		"estfundingrate":        this.HandleFundingRate,
	}
	var event *string = this.SafeString(message, "event")
	var method any = this.SafeValue(methods, event)
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message)
		return
	}
	var topic *string = this.SafeString(message, "topic")
	if topic != nil {
		method = this.SafeValue(methods, topic)
		if !ccxt.IsEqual(method, nil) {
			ccxt.CallDynamically(method, client, message)
			return
		}
		var splitTopic []string = strings.Split(*topic, "@")
		var splitLength int = len(splitTopic)
		if splitLength == 2 {
			var name *string = this.SafeString(splitTopic, 1)
			if name == nil {
				return
			}
			method = this.SafeValue(methods, name)
			if !ccxt.IsEqual(method, nil) {
				ccxt.CallDynamically(method, client, message)
				return
			}
			var splitName []string = strings.Split(*name, "_")
			var splitNameLength int = len(splitTopic)
			if splitNameLength == 2 {
				method = this.SafeValue(methods, this.SafeString(splitName, 0))
				if !ccxt.IsEqual(method, nil) {
					ccxt.CallDynamically(method, client, message)
				}
			}
		}
	}
}
